<?php
namespace App\Livewire\Admin\Tours; use App\Enums\TourStatus; use App\Models\Tour; use Livewire\Attributes\Url; use Livewire\Component; use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $search='';#[Url]public string $status='';public function render(){abort_unless(auth()->user()->isAdmin()||auth()->user()->isAccount(),403);$q=Tour::query()->with('leads')->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('tour_code','like','%'.$this->search.'%')->orWhere('name','like','%'.$this->search.'%')))->when($this->status,fn($q)=>$q->where('status',$this->status));return view('livewire.admin.tours.index',['tours'=>$q->orderByDesc('departure_date')->paginate(25),'statuses'=>TourStatus::options()])->layout('components.layouts.admin',['title'=>'Tours']);}}
